-- ── Phase 1: DROP existing tables (reverse dependency order) ──

DROP TABLE IF EXISTS medical_details CASCADE;
DROP TABLE IF EXISTS admissions CASCADE;
DROP TABLE IF EXISTS patients CASCADE;
DROP TABLE IF EXISTS admission_sources CASCADE;
DROP TABLE IF EXISTS discharge_dispositions CASCADE;
DROP TABLE IF EXISTS admission_types CASCADE;


-- ── Phase 2: CREATE tables ──


-- ──── Table: admission_types (Lookup table for patient admission types (Emergency, Urgent, Elective, etc.)) ────
DROP TABLE IF EXISTS admission_types CASCADE;
CREATE TABLE admission_types (
    admission_type_id INTEGER,
    description VARCHAR(100),
    PRIMARY KEY (admission_type_id)
);

-- ──── Table: discharge_dispositions (Lookup table for discharge destinations (Home, SNF, Expired, Hospice, etc.)) ────
DROP TABLE IF EXISTS discharge_dispositions CASCADE;
CREATE TABLE discharge_dispositions (
    discharge_disposition_id INTEGER,
    description VARCHAR(150),
    PRIMARY KEY (discharge_disposition_id)
);

-- ──── Table: admission_sources (Lookup table for admission referral sources (Physician, Emergency Room, Transfer, etc.)) ────
DROP TABLE IF EXISTS admission_sources CASCADE;
CREATE TABLE admission_sources (
    admission_source_id INTEGER,
    description VARCHAR(150),
    PRIMARY KEY (admission_source_id)
);

-- ──── Table: patients (Unique patient demographic profiles (deduplicated by patient_nbr)) ────
DROP TABLE IF EXISTS patients CASCADE;
CREATE TABLE patients (
    patient_nbr BIGINT,
    race VARCHAR(50),
    gender VARCHAR(20),
    age VARCHAR(20),
    weight VARCHAR(30),
    PRIMARY KEY (patient_nbr)
);

-- ──── Table: admissions (Hospital encounter logistics, hospital stay length, utilization, and readmission outcome) ────
DROP TABLE IF EXISTS admissions CASCADE;
CREATE TABLE admissions (
    encounter_id BIGINT,
    patient_nbr BIGINT,
    admission_type_id INTEGER,
    discharge_disposition_id INTEGER,
    admission_source_id INTEGER,
    time_in_hospital INTEGER,
    payer_code VARCHAR(20),
    medical_specialty VARCHAR(100),
    num_lab_procedures INTEGER,
    num_procedures INTEGER,
    num_medications INTEGER,
    number_outpatient INTEGER,
    number_emergency INTEGER,
    number_inpatient INTEGER,
    number_diagnoses INTEGER,
    readmitted VARCHAR(10),
    PRIMARY KEY (encounter_id)
);

-- ──── Table: medical_details (Clinical diagnosis codes (ICD-9), lab test results, diabetic medication changes, and prescription flags) ────
DROP TABLE IF EXISTS medical_details CASCADE;
CREATE TABLE medical_details (
    encounter_id BIGINT,
    diag_1 VARCHAR(20),
    diag_2 VARCHAR(20),
    diag_3 VARCHAR(20),
    max_glu_serum VARCHAR(20),
    a1c_result VARCHAR(20),
    metformin VARCHAR(20),
    repaglinide VARCHAR(20),
    nateglinide VARCHAR(20),
    chlorpropamide VARCHAR(20),
    glimepiride VARCHAR(20),
    acetohexamide VARCHAR(20),
    glipizide VARCHAR(20),
    glyburide VARCHAR(20),
    tolbutamide VARCHAR(20),
    pioglitazone VARCHAR(20),
    rosiglitazone VARCHAR(20),
    acarbose VARCHAR(20),
    miglitol VARCHAR(20),
    troglitazone VARCHAR(20),
    tolazamide VARCHAR(20),
    examide VARCHAR(20),
    citoglipton VARCHAR(20),
    insulin VARCHAR(20),
    glyburide_metformin VARCHAR(20),
    glipizide_metformin VARCHAR(20),
    glimepiride_pioglitazone VARCHAR(20),
    metformin_rosiglitazone VARCHAR(20),
    metformin_pioglitazone VARCHAR(20),
    change_med VARCHAR(10),
    diabetes_med VARCHAR(10),
    PRIMARY KEY (encounter_id)
);


